// Bun.serve: a fetch handler's Responses (text, JSON, empty, streamed, a file, an error) as a
// client sees them, routes, the client's address, and stopping. The same package under Bun
// prints the same.
export default async function run() {
  const server = Bun.serve({
    port: 0,
    routes: {
      "/users/:id": (req) => Response.json({ id: req.params.id }),
      "/static": new Response("static route"),
    },
    fetch(req, server) {
      const url = new URL(req.url);
      if (url.pathname === "/throw") throw new Error("boom");
      if (url.pathname === "/stream") {
        return new Response(new ReadableStream({
          async pull(c) {
            await Bun.sleep(1);
            c.enqueue(new TextEncoder().encode("chunk "));
            c.close();
          },
        }));
      }
      if (url.pathname === "/empty") return new Response(null, { status: 204 });
      if (url.pathname === "/echo") return req.text().then((t) => new Response(`${req.method} ${t} ${req.headers.get("x-test")}`));
      if (url.pathname === "/ip") return Response.json({ family: server.requestIP(req)?.family });
      if (url.pathname === "/async") return Bun.sleep(1).then(() => new Response("later", { status: 201, headers: { "x-a": "1" } }));
      return new Response(`hello ${url.pathname}${url.search}`);
    },
    error(e) {
      return new Response(`handled: ${e.message}`, { status: 500 });
    },
  });
  const base = `http://localhost:${server.port}`;
  console.log(typeof server.port, server.port > 0, server.hostname, server.url.href === `${base}/`);
  for (const path of ["/a?b=1", "/users/42", "/static", "/throw", "/stream", "/empty", "/ip", "/async"]) {
    const res = await fetch(base + path);
    console.log(path, res.status, res.headers.get("content-type")?.split(";")[0] ?? null, res.headers.get("x-a"), JSON.stringify(await res.text()));
  }
  const post = await fetch(`${base}/echo`, { method: "POST", body: "payload", headers: { "x-test": "yes" } });
  console.log("post", await post.text());
  const head = await fetch(`${base}/a`, { method: "HEAD" });
  console.log("head", head.status, head.headers.get("content-length"), JSON.stringify(await head.text()));
  await server.stop();
  console.log("stopped", await fetch(base).then(() => "still up", (e) => "refused"));
}
